            AppWidgetProviderInfo provider=null;for(AppWidgetProviderInfo candidate:AppWidgetManager.getInstance(activity).getInstalledProviders())if(candidate.provider.getClassName().endsWith(".FixtureWidgetProvider"))provider=candidate;check(provider!=null,"Widget fixture missing");LauncherWidgetHost host=new LauncherWidgetHost(isolated);widget[0]=host.allocateAppWidgetId();check(AppWidgetManager.getInstance(activity).bindAppWidgetIdIfAllowed(widget[0],provider.provider),"Could not bind fixture widget");long serial=activity.getSystemService(android.os.UserManager.class).getSerialNumberForUser(provider.getProfile());store.preferences.edit().putString("widget_ids_page_2",String.valueOf(widget[0])).putString("widget_provider_"+widget[0],provider.provider.flattenToString()).putLong("widget_user_"+widget[0],serial).putInt("widget_cell_x_"+widget[0],1).putInt("widget_cell_y_"+widget[0],3).putInt("widget_span_x_"+widget[0],2).putInt("widget_span_y_"+widget[0],2).putBoolean("widget_padding_"+widget[0],true).apply();store.save();
