    private static byte[] photo()throws Exception {Bitmap bitmap=Bitmap.createBitmap(48,72,Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xFF27A5A5);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);bitmap.recycle();return out.toByteArray();}
    private void delete(File file){File[] children=file.listFiles();if(children!=null)for(File child:children)delete(child);file.delete();}
    private Object field(Object object,String name){try{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception error){throw new AssertionError(error);}}
    private void invoke(String name,Object... arguments){try{Class<?>[] types=new Class<?>[arguments.length];for(int i=0;i<types.length;i++)types[i]=arguments[i].getClass();java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,arguments);}catch(Exception error){throw new AssertionError(error);}}
    private View find(String description){return find(activity.getWindow().getDecorView(),description);}
    private View find(View view,String description){if(view.getVisibility()!=View.VISIBLE)return null;if(description.contentEquals(java.util.Objects.toString(view.getContentDescription(),"")))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View result=find(group.getChildAt(i),description);if(result!=null)return result;}}return null;}
    private void setName(String value){long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo node=edit(test.getUiAutomation().getRootInActiveWindow());if(node!=null){Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);check(node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"Could not enter preset name");return;}SystemClock.sleep(100);}throw new AssertionError("Preset name editor missing");}
    private AccessibilityNodeInfo edit(AccessibilityNodeInfo node){if(node==null)return null;if("Preset name".contentEquals(java.util.Objects.toString(node.getContentDescription(),"")))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo found=edit(node.getChild(i));if(found!=null)return found;}return null;}
    private void systemClick(String label){long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label))if(label.equalsIgnoreCase(java.util.Objects.toString(node.getText(),""))&&node.isEnabled()&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK))return;SystemClock.sleep(100);}throw new AssertionError("Dialog action missing: "+label);}
    private void shell(String command)throws Exception {try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(test.getUiAutomation().executeShellCommand(command))){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}}
    private void main(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{task.run();}catch(Throwable failure){error.set(failure);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void await(BooleanSupplier ready,String message){long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){AtomicReference<Boolean> result=new AtomicReference<>(false);main(()->result.set(ready.getAsBoolean()));if(result.get())return;SystemClock.sleep(100);}throw new AssertionError(message);}
    private void capture(String name)throws Exception {SystemClock.sleep(700);Bitmap image=test.getUiAutomation().takeScreenshot();check(image!=null,"Screenshot unavailable");File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
